 1	method FindMax(a: array<int>) returns (i: int)
 2	  // Annotate this method with pre- and postconditions
 3	  // that ensure it behaves as described.
 4	  requires a.Length > 0
 5	  ensures 0<= i < a.Length
 6	  ensures forall k :: 0 <= k < a.Length ==> a[k] <= a[i] && k != 0
 7	{
 8	  // Fill in the body that calculates the INDEX of the maximum.
 9	  i := 0;
10	  var index := 1;
11	  while index < a.Length
12	    invariant 0 < index <= a.Length
13	    invariant 0 <= i < index
14	    invariant forall k :: 0 <= k < index ==> a[k] <= a[i]
15	  {
16	    if a[index] > a[i] {i:= index;}
17	    index := index + 1;
18	  }
19	}
